"""Exact integer and finite-field checks for the plane boundary of a family of curves.

Finite checks corroborate the universal proof; they are not substitutes for it.
"""
from math import gcd


def exponents(p, n):
    return [(p ** (2 * i) - 1) // (2 * (p - 1)) for i in range(1, n + 1)]


def gap_count(a, b):
    # Exact Apéry formula for a numerical semigroup generated by coprime a, b.
    assert gcd(a, b) == 1
    ap = sorted((j * b for j in range(a)), key=lambda t: t % a)
    return sum(ap) // a - (a - 1) // 2 if a % 2 else (2 * sum(ap) - a * (a - 1)) // (2 * a)


def explicit_gaps(a, b):
    # Independent exhaustive enumeration up to conductor.
    c = (a - 1) * (b - 1)
    reachable = [False] * max(c, 1)
    reachable[0] = True
    for z in range(1, c):
        reachable[z] = (z >= a and reachable[z - a]) or (z >= b and reachable[z - b])
    return sum(not ok for ok in reachable), (c - 1 >= 0 and not reachable[c - 1])


def check(p, n):
    ee = exponents(p, n)
    d = ee[-1]
    a, b = d - p - 1, d - 1
    assert d > p + 2 and a > 1 and b > a and gcd(a, b) == 1
    assert d % p == pow(2, -1, p) and (a % p) != 0 and (b % p) != 0
    assert ee == sorted(ee)
    assert ee[0] == (p + 1) // 2
    # Terms of the projective local equation at Q=[0:1:0].
    # a*b^(d-p-1) + b^(d-1) + b^d + 2*sum(a^e*b^(d-e))
    terms = [(1, a), (0, d - 1), (0, d)] + [(i, d - i) for i in ee]
    first_degree = min(x + y for x, y in terms)
    initial_terms = [(x, y) for x, y in terms if x + y == first_degree]
    assert first_degree == d - p and initial_terms == [(1, a)]
    # Branch 0 is parametrized by b=1/v; u=-b^(p-1)+O(b^p).
    # Therefore ord(b)=1 and ord(a=u*b)=p at this branch.
    # Branch infinity: ord(u)=-p, ord(v)=-(d-1), giving ord(a)=a, ord(b)=b.
    assert a < p * b
    delta_cusp = (a - 1) * (b - 1) // 2
    delta_total = delta_cusp + a
    arithmetic_genus = (d - 1) * (d - 2) // 2
    normalized_genus = (p - 1) * d // 2
    assert arithmetic_genus - delta_total == normalized_genus
    assert normalized_genus == (p ** (2 * n) - 1) // 4
    assert a + b == 2 * d - p - 2
    # The line at infinity cuts the smooth branch once and the cusp d-1 times.
    assert 1 + b == d
    # Conductor valuations in the normalization at the two branches.
    c_smooth, c_cusp = a, 2 * delta_cusp + a
    assert c_smooth + c_cusp == 2 * delta_total
    assert gap_count(a, b) == delta_cusp
    if d < 250:
        assert explicit_gaps(a, b) == (delta_cusp, True)
    print(f'CHECK_OK p={p} n={n} degree={d} contact={a} cusp_pair=({a},{b}) '
          f'delta={delta_total} genus={normalized_genus}')


if __name__ == '__main__':
    for prime in (3, 5, 7, 11, 13):
        for height in (2, 3):
            check(prime, height)
    print('ALL_EXACT_CHECKS_OK')
